'use strict';
const $=id=>document.getElementById(id),canvas=$('photo'),ctx=canvas.getContext('2d',{willReadFrequently:true});
let original=null,result=null,selected=0,segmented=false,started=null,clock=null,notes=[],imageGeneration=0;
const hex=rgb=>'#'+rgb.map(x=>x.toString(16).padStart(2,'0')).join('');
const colorWords=[['leaf green',[73,104,53]],['olive',[132,133,69]],['ochre',[190,145,58]],['earth brown',[112,78,52]],['stone gray',[141,145,135]],['sky blue',[130,180,202]],['rust',[180,87,46]],['cream',[226,221,191]],['deep green',[31,62,43]],['rose',[173,93,122]],['violet',[108,84,146]]].map(([name,rgb])=>({name,lab:GroundLens.rgbToLab(rgb)}));
function word(rgb){return colorWords[GroundLens.nearest(GroundLens.rgbToLab(rgb),colorWords.map(x=>x.lab)).index].name;}
function loadNotes(){try{const n=JSON.parse(localStorage.getItem('groundlens-notes')||'[]');notes=Array.isArray(n)?n.filter(x=>typeof x.note==='string'&&typeof x.at==='string').slice(-100):[];}catch{notes=[];}renderNotes();}
function renderNotes(){$('count').textContent=notes.length;$('notes').replaceChildren();if(!notes.length){const p=document.createElement('p');p.textContent='Your next observation belongs here.';p.className='small';$('notes').append(p);}for(const n of notes.slice(-5).reverse()){const a=document.createElement('article'),t=document.createElement('small'),p=document.createElement('p');t.textContent=new Date(n.at).toLocaleDateString()+' · '+(n.color||'observation');p.textContent=n.note;a.append(t,p);$('notes').append(a);}}
function demo(){imageGeneration++;canvas.width=720;canvas.height=460;ctx.fillStyle='#c3d7d4';ctx.fillRect(0,0,720,460);ctx.fillStyle='#809b69';ctx.beginPath();ctx.moveTo(0,245);ctx.quadraticCurveTo(160,135,400,260);ctx.quadraticCurveTo(590,160,720,190);ctx.lineTo(720,460);ctx.lineTo(0,460);ctx.fill();ctx.fillStyle='#bda576';ctx.beginPath();ctx.moveTo(322,245);ctx.lineTo(420,245);ctx.lineTo(610,460);ctx.lineTo(195,460);ctx.fill();for(const [x,y,r,c] of [[80,320,85,'#3d6545'],[180,252,75,'#587c50'],[610,280,108,'#456b45'],[520,390,52,'#9d7c43'],[130,410,63,'#788b50']]){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x,y,r,r*.65,-.4,0,7);ctx.fill();}ctx.strokeStyle='#f0e0b1';ctx.lineWidth=3;for(let i=0;i<9;i++){ctx.beginPath();ctx.moveTo(41+i*19,459);ctx.quadraticCurveTo(52+i*18,393,38+i*20,348+(i%3)*13);ctx.stroke();}ctx.fillStyle='#e7c569';for(let i=0;i<8;i++){ctx.beginPath();ctx.arc(550+(i%4)*31,327+Math.floor(i/4)*32,7,0,7);ctx.fill();}$('image-label').textContent='Synthetic garden · demo';analyzeImage();}
function analyzeImage(){original=ctx.getImageData(0,0,canvas.width,canvas.height);segmented=false;$('segment').setAttribute('aria-pressed','false');$('segment').textContent='Show learned regions';const pixels=[],data=original.data,step=Math.max(1,Math.ceil(canvas.width*canvas.height/6500));for(let i=0;i<canvas.width*canvas.height;i+=step){if(data[i*4+3]>=200)pixels.push(Array.from(data.slice(i*4,i*4+3)));}const before=performance.now();try{result=GroundLens.analyze(pixels);}catch(e){$('status').textContent=e.message;return;}const ms=Math.round(performance.now()-before);selected=0;$('palette').replaceChildren();result.colors.forEach((c,i)=>{let b=document.createElement('button');b.className='swatch';b.setAttribute('aria-pressed',i===0?'true':'false');b.setAttribute('aria-label',word(c.rgb)+', '+hex(c.rgb)+', '+Math.round(c.share*100)+' percent');const chip=document.createElement('span');chip.className='chip';chip.style.background=hex(c.rgb);const title=document.createElement('b');title.textContent=hex(c.rgb);const sub=document.createElement('span');sub.textContent=Math.round(c.share*100)+'%';b.append(chip,title,sub);b.addEventListener('click',()=>selectColor(i));$('palette').append(b);});$('status').textContent=result.lowVariation?'Very little color variation. Try a more varied scene, or explore its textures.':result.colors.length+' colors learned locally · '+ms+' ms';$('metrics').textContent=`This image: ${result.trainPixels} training pixels; ${result.heldoutPixels} held-out pixels. Mean held-out error: ${result.holdoutError.toFixed(2)} ΔE76; single-mean baseline: ${result.baselineError.toFixed(2)} ΔE76. ${result.iterations} fitting iterations in the selected restart.`;selectColor(0);}
function selectColor(i){if(!result||!Number.isInteger(i)||i<0||i>=result.colors.length)throw Error('Choose an available palette index.');selected=i;[...$('palette').children].forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));const c=result.colors[i];$('mission-text').textContent=`Look for this ${word(c.rgb)} (${hex(c.rgb)}) in two different places. Notice what changes with light, distance or texture. Observe without picking or disturbing anything.`;return {index:i,color:hex(c.rgb),mission:$('mission-text').textContent};}
$('upload').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>12*1024*1024){$('status').textContent='Please choose an image smaller than 12 MB.';return;}if(!['image/jpeg','image/png','image/webp','image/avif'].includes(file.type)){$('status').textContent='Please choose a JPG, PNG, WebP or AVIF image.';return;}const generation=++imageGeneration;const url=URL.createObjectURL(file),img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url;});if(generation!==imageGeneration)return;const scale=Math.min(1,720/Math.max(img.width,img.height));canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);$('image-label').textContent='Your photo · local analysis';analyzeImage();}catch{$('status').textContent='This image could not be read. Try another photo.';}finally{URL.revokeObjectURL(url);e.target.value='';}});
$('demo').addEventListener('click',demo);
$('segment').addEventListener('click',()=>{if(!result||!original)return;segmented=!segmented;$('segment').setAttribute('aria-pressed',String(segmented));$('segment').textContent=segmented?'Show original image':'Show learned regions';if(!segmented){ctx.putImageData(original,0,0);return;}const out=new ImageData(new Uint8ClampedArray(original.data),original.width,original.height),centers=result.colors.map(c=>c.lab);for(let i=0;i<out.data.length;i+=4){const n=GroundLens.nearest(GroundLens.rgbToLab(Array.from(out.data.slice(i,i+3))),centers);result.colors[n.index].rgb.forEach((v,j)=>out.data[i+j]=v);}ctx.putImageData(out,0,0);});
$('start').addEventListener('click',()=>{started=Date.now();$('outside').hidden=false;$('outside-text').textContent=$('mission-text').textContent;$('journal').hidden=true;clearInterval(clock);const tick=()=>{const s=Math.floor((Date.now()-started)/1000);$('timer').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');};tick();clock=setInterval(tick,1000);$('outside').scrollIntoView({behavior:'smooth',block:'start'});$('outside').focus({preventScroll:true});});
$('return').addEventListener('click',()=>{clearInterval(clock);$('outside').hidden=true;$('journal').hidden=false;$('journal').scrollIntoView({behavior:'smooth'});$('note').focus({preventScroll:true});});
$('save').addEventListener('click',()=>{const note=$('note').value.trim();if(!note){$('save-status').textContent='Write one observation first.';return;}const item={at:new Date().toISOString(),note,color:hex(result.colors[selected].rgb),elapsedSeconds:started?Math.floor((Date.now()-started)/1000):null};const next=[...notes,item].slice(-100);try{localStorage.setItem('groundlens-notes',JSON.stringify(next));notes=next;renderNotes();$('note').value='';$('save-status').textContent='Saved on this device. No photo or location was stored.';}catch{$('save-status').textContent='Device storage is unavailable. Copy your note before leaving.';}});
$('export').addEventListener('click',()=>{const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify({app:'GroundLens',version:1,notes},null,2)],{type:'application/json'}));a.href=u;a.download='groundlens-notes.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);});
$('clear').addEventListener('click',()=>{if(!notes.length)return;if(!confirm('Erase all GroundLens notes saved on this device?'))return;try{localStorage.removeItem('groundlens-notes');notes=[];renderNotes();}catch{$('save-status').textContent='Could not clear device storage.';}});
loadNotes();demo();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_groundlens_palette',description:'Read the locally learned color palette and current observation mission.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({colors:result.colors.map(c=>({hex:hex(c.rgb),share:c.share})),mission:$('mission-text').textContent})},{name:'select_groundlens_color',description:'Select an existing palette color and update the visible observation mission. Does not start a timer or save a note.',inputSchema:{type:'object',properties:{index:{type:'integer',minimum:0,maximum:4}},required:['index'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>selectColor(input.index)}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
